mapper.select:
SELECT EXISTS(
    SELECT 1 FROM customer_sessions
    WHERE id = #{id,jdbcType=OTHER}
      AND user_id = #{userId,jdbcType=OTHER}
      AND deleted_at IS NULL
)

mapper.update:
UPDATE customer_sessions
SET updated_at = #{updatedAt}
WHERE id = #{id,jdbcType=OTHER}

UPDATE customer_sessions
SET deleted_at = #{deletedAt}
WHERE id = #{id,jdbcType=OTHER}
  AND user_id = #{userId,jdbcType=OTHER}
